pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Ensure contract starts with 0 balance
        assertEq(address(c).balance, 0);
        // Call go() with 1 wei; send from owner to avoid any prank issues with owner being msg.sender
        vm.deal(address(this), 1 wei);
        vm.prank(address(this));
        c.go{value: 1 wei}();
        // After the call, reference transfers its 1 wei to owner, so balance is 0
        // Buggy version does not transfer, so balance remains 1 wei
        assertTrue(address(c).balance == 0);
    }
}

