// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        vm.etch(target, hex"FE"); // minimal reverting code (INVALID)
        vm.prank(address(0x1));
        bool ok;
        try c.go{value: 1 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: go reverts because send to target fails, so c.balance unchanged (1 ether).
        // Bug: go sends 0 to target (succeeds), then sends entire balance to owner, so c.balance becomes 0.
        assertTrue(ok == false && address(c).balance == 1 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the user with 1 ether
        vm.deal(address(this), 1 ether);
        // Call go() with 1 ether; the external call to target will revert (no fallback on target)
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("go()"));
        // For the reference: go() forwards msg.value to target, target reverts, go() reverts, so success==false, c.balance==1 ether
        // For the mutant: go() sends 0 to target, target returns true, then transfer(c.balance=1 ether) to owner, so success==true, c.balance==0
        // Check that the reference contract (or buggy) leaves c.balance at 1 ether
        assertTrue(address(c).balance == 1 ether);
    }
}
